            {"question":"Gerontology is the study of:","options":["Diseases of older adults only","Physical, psychological, social, and spiritual aspects of old age","Nursing procedures for elderly patients only","Medical treatment of chronic diseases"],"answer":"Physical, psychological, social, and spiritual aspects of old age"},
            {"question":"Geriatrics is:","options":["The study of social aspects of aging","A branch of general medicine concerned with diseases and illness of older adults","A branch of nursing concerned with elderly care","The study of retirement and social security"],"answer":"A branch of general medicine concerned with diseases and illness of older adults"},
            {"question":"Gerontological nursing is primarily concerned with:","options":["Diagnosing diseases only","Assessment, planning, implementation, and evaluation of care for older adults","Providing social services only","Treating psychiatric disorders only"],"answer":"Assessment, planning, implementation, and evaluation of care for older adults"},
            {"question":"According to the lecture, an elderly person is someone who is:","options":["55 years or older","60 years or older","65 years or older","70 years or older"],"answer":"60 years or older"},
