            {"question":"The social position of older people is determined mainly by:","options":["Age alone","Culture","Income only","Physical health only"],"answer":"Culture"},
            {"question":"Ageism refers to:","options":["Positive attitudes toward older adults","An unfavorable and prejudiced attitude toward older adults simply because they are old","Fear of retirement","Social isolation caused by disease"],"answer":"An unfavorable and prejudiced attitude toward older adults simply because they are old"},
            {"question":"Stereotypes are best described as:","options":["Accurate beliefs based on individual assessment","Simplified and often untrue beliefs that reinforce negative images of older people","Medical diagnoses of elderly patients","Social roles assigned by healthcare workers"],"answer":"Simplified and often untrue beliefs that reinforce negative images of older people"},
            {"question":"A person aged 68 years is classified as:","options":["Old-old","Very old","Young old","Centenarian"],"answer":"Young old"},
