            {"question":"Gerontology focuses only on diseases affecting older adults.","options":["True","False"],"answer":"False"},
            {"question":"Geriatrics is a branch of general medicine concerned with diseases and illness of older adults.","options":["True","False"],"answer":"True"},
            {"question":"Gerontological nursing includes assessment, planning, implementation, and evaluation of care.","options":["True","False"],"answer":"True"},
