            {"question":"Ageism refers to favorable attitudes toward older adults.","options":["True","False"],"answer":"False"},
            {"question":"Stereotypes are always accurate beliefs about older adults.","options":["True","False"],"answer":"False"},
            {"question":"People aged 75–84 years are classified as old-old.","options":["True","False"],"answer":"True"},
            {"question":"People aged 100 years and older are classified as centenarians.","options":["True","False"],"answer":"True"},
            {"question":"Which age-related change occurs to hair?","options":["Hair becomes thicker and darker","Hair loses color and becomes gray","Hair growth increases","Hair becomes more elastic"],"answer":"Hair loses color and becomes gray"},
            {"question":"Which nail change is expected with aging?","options":["Nails become soft and flexible","Nails become thin and smooth","Nails become thick and brittle","Nails become more elastic"],"answer":"Nails become thick and brittle"},
            {"question":"An older adult complains of increased sensitivity to temperature. This finding is:","options":["An expected age-related integumentary change","A sign of increased sweat gland activity","A sign of increased skin elasticity","An indication of improved circulation"],"answer":"An expected age-related integumentary change"},
            {"question":"Which intervention is MOST appropriate for routine skin care in an older adult?","options":["Use strong soap frequently","Use mild soap","Avoid moisturizing products","Bathe several times every day"],"answer":"Use mild soap"},
