            {"question":"How often does the lecture recommend bathing or showering for an older adult?","options":["Several times daily","Once or twice a week","Once every two weeks","Only when sweating occurs"],"answer":"Once or twice a week"},
            {"question":"Which intervention is recommended to alleviate an older person's feeling of coldness?","options":["Avoid layers of clothing","Use socks, sweaters, and layers of clothing","Use cold-water baths","Reduce clothing during winter"],"answer":"Use socks, sweaters, and layers of clothing"},
            {"question":"Which statement about the cardiovascular system with aging is CORRECT?","options":["Heart size increases significantly","Cardiac output increases","Heart size does not change with age","Heart muscle becomes more elastic"],"answer":"Heart size does not change with age"},
            {"question":"Which cardiovascular change occurs with aging?","options":["Increased cardiac output","Increased elasticity of arteries","Decreased cardiac output","Increased heart rate"],"answer":"Decreased cardiac output"},
            {"question":"A decrease in elasticity of the heart muscle and arteries is associated with:","options":["Aging","Increased exercise tolerance","Improved circulation","Increased cardiac output"],"answer":"Aging"},
            {"question":"Which blood pressure change is mentioned as an age-related cardiovascular change?","options":["Blood pressure decreases","Blood pressure remains unchanged","Blood pressure increases","Blood pressure disappears"],"answer":"Blood pressure increases"},
            {"question":"A nurse is caring for an elderly patient with cardiovascular changes. Which activity recommendation is MOST appropriate?","options":["Encourage excessive exercise","Avoid all exercise","Encourage moderate exercise according to individual tolerance","Encourage exercise without rest periods"],"answer":"Encourage moderate exercise according to individual tolerance"},
            {"question":"For an older adult with high blood pressure, the lecture recommends:","options":["A high-salt diet","Decreased fat intake and a low-salt diet","Avoiding all physical activity","Increasing fat intake"],"answer":"Decreased fat intake and a low-salt diet"},
            {"question":"Which respiratory change is expected with aging?","options":["Respiratory muscles become stronger","Respiratory muscles become weaker","Rib cage becomes more flexible","Alveoli become more elastic"],"answer":"Respiratory muscles become weaker"},
