            {"question":"Parkinson's disease affects approximately how many people in the United States?","options":["500,000","1 million","2 million","7 million"],"answer":"1 million"},
            {"question":"According to the lecture, the prevalence of Parkinson's disease rises from approximately 1% in people over 60 to:","options":["2% over 70 years","3% over 75 years","4% over 80 years","5% over 90 years"],"answer":"4% over 80 years"},
            {"question":"The mean age of onset of Parkinson's disease is approximately:","options":["40 years","50 years","60 years","70 years"],"answer":"60 years"},
            {"question":"Young-onset Parkinson's disease refers to cases beginning between:","options":["10–20 years","20–50 years","40–60 years","50–70 years"],"answer":"20–50 years"},
            {"question":"Approximately what percentage of Parkinson's disease cases are classified as young-onset PD?","options":["1–2%","5–10%","15–20%","25–30%"],"answer":"5–10%"},
            {"question":"Which statement regarding sex differences in Parkinson's disease is MOST accurate according to the lecture?","options":["It is definitely more common in women.","It is definitely more common in men.","Some studies suggested greater occurrence in men, while others found no difference.","It occurs exclusively in men."],"answer":"Some studies suggested greater occurrence in men, while others found no difference."},
            {"question":"Parkinson's disease is best described as:","options":["An acute infectious disorder of the peripheral nervous system","A slowly progressive degenerative disorder of the central nervous system","A reversible muscular disorder","A congenital skeletal disorder"],"answer":"A slowly progressive degenerative disorder of the central nervous system"},
            {"question":"The primary brain region involved in Parkinson's disease according to the lecture is the:","options":["Cerebellum","Hippocampus","Substantia nigra","Medulla"],"answer":"Substantia nigra"},
            {"question":"Parkinson's disease results from progressive loss of:","options":["Nigrostriatal dopaminergic function","Corticospinal cholinergic function","Cerebellar serotonergic function","Peripheral adrenergic function"],"answer":"Nigrostriatal dopaminergic function"},
            {"question":"The main neurotransmitter deficiency associated with Parkinson's disease is:","options":["Acetylcholine","Dopamine","Serotonin","GABA"],"answer":"Dopamine"},
            {"question":"Degeneration of neurons in the substantia nigra causes dopamine deficiency primarily in the:","options":["Cerebral cortex","Basal ganglia","Spinal cord","Cerebellum"],"answer":"Basal ganglia"},
            {"question":"Dopamine deficiency results in:","options":["Decreased acetylcholine effect","Increased acetylcholine effect","Complete absence of acetylcholine","Increased serotonin effect"],"answer":"Increased acetylcholine effect"},
            {"question":"Which group of manifestations is associated with cholinergic excess according to the lecture?","options":["Rigidity, tremors, bradykinesia, and postural instability","Fever, seizures, and diarrhea","Hypertension, tachycardia, and hyperactivity","Blindness, deafness, and aphasia"],"answer":"Rigidity, tremors, bradykinesia, and postural instability"},
            {"question":"Which of the following is listed as a possible risk factor for Parkinson's disease?","options":["Gene mutation","Toxins","Trauma","All of the above"],"answer":"All of the above"},
            {"question":"Which statement about the exact cause of Parkinson's disease is CORRECT?","options":["It is completely established.","It is still unknown.","It is always caused by trauma.","It is always caused by gene mutation."],"answer":"It is still unknown."},
            {"question":"Which of the following represents an early symptom of Parkinson's disease?","options":["Lack of facial expression","Severe dementia","Urinary incontinence only","Complete loss of speech"],"answer":"Lack of facial expression"},
            {"question":"The four cardinal features of Parkinson's disease include:","options":["Tremor, fever, weakness, and headache","Muscle rigidity, resting tremor, bradykinesia, and postural instability","Dementia, depression, constipation, and pain","Dysphagia, aphasia, blindness, and seizures"],"answer":"Muscle rigidity, resting tremor, bradykinesia, and postural instability"},
            {"question":"A patient whose arm becomes stiff when it is moved is demonstrating:","options":["Bradykinesia","Muscle rigidity","Postural instability","Resting tremor"],"answer":"Muscle rigidity"},
            {"question":"Which finding is characteristic of hypomimia?","options":["Excessive facial expression","Mask-like face with lack of facial expression","Rapid facial movements","Facial paralysis with complete loss of sensation"],"answer":"Mask-like face with lack of facial expression"},
            {"question":"An older patient has an open mouth with drooling and a mask-like facial appearance. These findings are most closely associated with:","options":["Muscle rigidity","Dementia","Depression","Urinary incontinence"],"answer":"Muscle rigidity"},
            {"question":"According to the image on page 6, Parkinson's disease is associated with a visibly:","options":["Enlarged substantia nigra","Diminished substantia nigra","Enlarged cerebellum","Diminished cerebral cortex"],"answer":"Diminished substantia nigra"},
