            {"question":"The characteristic movement of Parkinson's resting tremor is described as:","options":["Yes-yes movement","No-no movement","Pill-rolling movement","Flapping movement"],"answer":"Pill-rolling movement"},
            {"question":"Parkinson's disease is the second most common neurodegenerative disorder after Alzheimer's disease.","options":["True","False"],"answer":"True"},
            {"question":"The mean age of onset of Parkinson's disease is approximately 60 years.","options":["True","False"],"answer":"True"},
            {"question":"Young-onset Parkinson's disease begins between 20 and 50 years of age.","options":["True","False"],"answer":"True"},
            {"question":"The exact cause of Parkinson's disease is completely known.","options":["True","False"],"answer":"False"},
            {"question":"Gene mutation, toxins, and trauma are mentioned as possible risk factors.","options":["True","False"],"answer":"True"},
            {"question":"Parkinson's disease results from dopamine deficiency.","options":["True","False"],"answer":"True"},
