            {"question":"Dopamine agonists work by:","options":["Blocking ACh receptors","Activating dopamine receptors","Blocking dopamine receptors","Increasing muscle rigidity"],"answer":"Activating dopamine receptors"},
            {"question":"Which adverse effects are listed for dopamine agonists?","options":["Nausea, vomiting, hypotension, and mental changes","Dry mouth, blurred vision, and confusion","Fever, hypertension, and diarrhea","Constipation and urinary incontinence only"],"answer":"Nausea, vomiting, hypotension, and mental changes"},
            {"question":"Artane belongs to which drug class?","options":["Dopaminergic","Dopamine agonist","Anticholinergic","Cholinergic"],"answer":"Anticholinergic"},
            {"question":"The mechanism of action of Artane is:","options":["Activate dopamine receptors","Block ACh receptors","Activate ACh receptors","Block dopamine receptors"],"answer":"Block ACh receptors"},
            {"question":"Which combination is associated with anticholinergic therapy using Artane?","options":["Nausea, vomiting, and hypotension","Dry mouth, blurred vision, and confusion","Bradycardia, diarrhea, and fever","Tremor, constipation, and hypertension"],"answer":"Dry mouth, blurred vision, and confusion"},
            {"question":"During nursing assessment, which information should be obtained FIRST regarding the patient's symptoms?","options":["The patient's favorite activities","The length of time the symptoms have been present","The patient's educational level","The patient's previous occupations"],"answer":"The length of time the symptoms have been present"},
